from collections import Counter

_FACE_VALUES = {"J": 11, "Q": 12, "K": 13, "A": 14}


def _card_rank(card):
    value = card[:-1]
    return int(value) if value.isdigit() else _FACE_VALUES[value]


def _is_straight(ranks):
    """Return the highest card of the straight, or None if not a straight."""
    if len(set(ranks)) != 5:
        return None
    high = max(ranks)
    if high - min(ranks) == 4:
        return high
    # Ace can be low: A-2-3-4-5 is a 5-high straight.
    if ranks == [14, 5, 4, 3, 2]:
        return 5
    return None


def _score_hand(hand):
    cards = hand.split()
    ranks = sorted((_card_rank(card) for card in cards), reverse=True)
    flush = len({card[1] for card in cards}) == 1
    straight_high = _is_straight(ranks)

    counts = Counter(ranks)
    # Group ranks by (count, rank) descending: e.g. full house ->
    # [(triplet_rank, 3), (pair_rank, 2)], two pair -> [(high, 2), (low, 2), (kicker, 1)].
    groups = sorted(counts.items(), key=lambda item: (item[1], item[0]), reverse=True)
    tiebreak = [rank for rank, _ in groups]

    if flush and straight_high is not None:
        category = 8
        tiebreak = [straight_high]
    elif max(counts.values()) == 4:
        category = 7
    elif max(counts.values()) == 3 and min(counts.values()) == 2:
        category = 6
    elif flush:
        category = 5
        tiebreak = ranks
    elif straight_high is not None:
        category = 4
        tiebreak = [straight_high]
    elif max(counts.values()) == 3:
        category = 3
    elif sum(1 for _, count in groups if count == 2) == 2:
        category = 2
    elif max(counts.values()) == 2:
        category = 1
    else:
        category = 0

    return (category, *tiebreak)


def best_hands(hands):
    scored = [(_score_hand(hand), hand) for hand in hands]
    best = max(score for score, _ in scored)
    return [hand for score, hand in scored if score == best]
